            for (Node n : nodes) {
                pq.add(n);
            }

            while (pq.size() > 1) {
                Node n1 = pq.poll();
                Node n2 = pq.poll();
                Node parent = new Node(-1, n1.weight + n2.weight);
                parent.left = n1;
                parent.right = n2;
                pq.add(parent);
            }

            Node root = pq.poll();
            int[] depths = new int[alphaSize];
