private static void heapifyDown(int[] heap, int[] weight, int nHeap, int idx) {
    int zz = idx;
    int tmp = heap[zz];
    while (true) {
        int yy = zz << 1;
        if (yy > nHeap) break;
        if (yy < nHeap && weight[heap[yy + 1]] < weight[heap[yy]]) yy++;
        if (weight[tmp] < weight[heap[yy]]) break;
        heap[zz] = heap[yy];
        zz = yy;
    }
    heap[zz] = tmp;
}

