    /**
     * Helper class that implements a min-heap for Huffman tree construction.
     */
    private static final class HuffmanHeap {
        final int[] heap;
        final int[] weight;
        int size;

        HuffmanHeap(int maxSize, int[] weight) {
            this.heap = new int[maxSize];
            this.weight = weight;
            this.size = 0;
        }

        void push(int node) {
            size++;
            heap[size] = node;
            siftUp(size);
        }

        int pop() {
            int node = heap[1];
            heap[1] = heap[size];
            size--;
            siftDown(1);
            return node;
        }

        private void siftUp(int idx) {
            int node = heap[idx];
            while (idx > 1 && weight[node] < weight[heap[idx >> 1]]) {
                heap[idx] = heap[idx >> 1];
                idx >>= 1;
            }
            heap[idx] = node;
        }

        private void siftDown(int idx) {
            int node = heap[idx];
            while (true) {
                int left = idx << 1;
                if (left > size) break;
                int right = left + 1;
                int child = left;
                if (right <= size && weight[heap[right]] < weight[heap[left]]) {
                    child = right;
                }
                if (weight[node] <= weight[heap[child]]) break;
                heap[idx] = heap[child];
                idx = child;
            }
            heap[idx] = node;
        }
    }

