    private static void initWeights(int[] freq, int[] weight, int alphaSize) {
        for (int i = alphaSize; --i >= 0;) {
            weight[i + 1] = (freq[i] == 0 ? 1 : freq[i]) << 8;
        }
    }

    /**
     * Computes the code lengths for each symbol and checks if any length
     * exceeds {@code maxLen}.  Returns {@code true} if a length is too long.
     */
    private static boolean computeLengths(char[] len, int[] parent,
                                          int alphaSize, int maxLen) {
        boolean tooLong = false;
        for (int i = 1; i <= alphaSize; i++) {
            int depth = 0;
            int k = i;
            while (parent[k] >= 0) {
                k = parent[k];
                depth++;
            }
            len[i - 1] = (char) depth;
            if (depth > maxLen) {
                tooLong = true;
            }
        }
        return tooLong;
    }

    /**
     * Adjusts the weights when a code length exceeds {@code maxLen}.
     */
    private static void adjustWeights(int[] weight, int alphaSize) {
        for (int i = 1; i < alphaSize; i++) {
            int j = weight[i] >> 8;
            j = 1 + (j >> 1);
            weight[i] = j << 8;
        }
    }

    /**
     * Combines two node weights into a new parent weight.
     */
    private static int combineWeights(int w1, int w2) {
        int high = (w1 & 0xffffff00) + (w2 & 0xffffff00);
        int low = 1 + ((w1 & 0x000000ff) > (w2 & 0x000000ff)
                       ? (w1 & 0x000000ff) : (w2 & 0x000000ff));
        return high | low;
    }
}

