    /* Helper methods for hbMakeCodeLengths */

    /**
     * Initializes the weight array based on the frequency array.
     */
    private static void initWeights(int[] weight, int[] freq, int alphaSize) {
        for (int i = alphaSize; --i >= 0;) {
            weight[i + 1] = (freq[i] == 0 ? 1 : freq[i]) << 8;
        }
    }

    /**
     * Builds the initial min-heap from the weight array.
     */
    private static void buildInitialHeap(int[] heap, int[] weight,
                                         int[] parent, int nHeap,
                                         int alphaSize) {
        for (int i = 1; i <= alphaSize; i++) {
            parent[i] = -1;
            nHeap++;
            heap[nHeap] = i;
            siftUp(heap, weight, nHeap);
        }
    }

    /**
     * Builds the Huffman tree using the heap and updates parent and weight arrays.
     */
    private static void buildHuffmanTree(int[] heap, int[] weight,
                                         int[] parent, int alphaSize,
                                         int nHeap) {
        int nNodes = alphaSize;
        while (nHeap > 1) {
            int n1 = heap[1];
            heap[1] = heap[nHeap];
            nHeap--;
            siftDown(heap, weight, 1, nHeap);

            int n2 = heap[1];
            heap[1] = heap[nHeap];
            nHeap--;
            siftDown(heap, weight, 1, nHeap);

            nNodes++;
            parent[n1] = parent[n2] = nNodes;

            int weight_n1 = weight[n1];
            int weight_n2 = weight[n2];
            weight[nNodes] = ((weight_n1 & 0xffffff00) + (weight_n2 & 0xffffff00))
                | (1 + Math.max(weight_n1 & 0xff, weight_n2 & 0xff));
            parent[nNodes] = -1;

            nHeap++;
            heap[nHeap] = nNodes;
            siftUp(heap, weight, nHeap);
        }
    }

    /**
     * Computes code lengths from the parent array and checks for overlong codes.
     */
    private static boolean computeLengths(char[] len, int[] parent,
                                          int alphaSize, int maxLen) {
        boolean tooLong = false;
        for (int i = 1; i <= alphaSize; i++) {
            int depth = 0;
            int k = i;
            while (parent[k] >= 0) {
                k = parent[k];
                depth++;
            }
            len[i - 1] = (char) depth;
            if (depth > maxLen) {
                tooLong = true;
            }
        }
        return tooLong;
    }

    /**
     * Adjusts weights when code lengths exceed the maximum allowed length.
     */
    private static void adjustWeights(int[] weight, int alphaSize) {
        for (int i = 1; i < alphaSize; i++) {
            int j = weight[i] >> 8;
            j = 1 + (j >> 1);
            weight[i] = j << 8;
        }
    }

    /**
     * Restores the heap property by moving the element at idx up.
     */
    private static void siftUp(int[] heap, int[] weight, int idx) {
        int tmp = heap[idx];
        while (idx > 1 && weight[tmp] < weight[heap[idx >> 1]]) {
            heap[idx] = heap[idx >> 1];
            idx >>= 1;
        }
        heap[idx] = tmp;
    }

    /**
     * Restores the heap property by moving the element at idx down.
     */
    private static void siftDown(int[] heap, int[] weight, int idx,
                                 int heapSize) {
        int tmp = heap[idx];
        while (true) {
            int left = idx << 1;
            if (left > heapSize) {
                break;
            }
            int right = left + 1;
            if (right <= heapSize && weight[heap[right]] < weight[heap[left]]) {
                left = right;
            }
            if (weight[tmp] <= weight[heap[left]]) {
                break;
            }
            heap[idx] = heap[left];
            idx = left;
        }
        heap[idx] = tmp;
    }
}

